import path from 'node:path'
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'
import { viteSingleFile } from 'vite-plugin-singlefile'

// Relative base so dist/ works from any host or sub-folder.
// - `npm run build`: one HTML page per language and page (generated by scripts/pages.mjs) sharing
//   lazily loaded chunks. This is what gets deployed.
// - `npm run build:standalone`: a single index.html with all JS, CSS and fonts inlined and hash
//   routing, so the site also opens by double-clicking it (browsers block external scripts on file://).
export default defineConfig(({ mode }) => {
  const standalone = mode === 'standalone'
  return {
    base: './',
    plugins: [react(), tailwindcss(), standalone && viteSingleFile()],
    resolve: {
      alias: { '@': path.resolve(import.meta.dirname, './src') },
    },
    build: {
      chunkSizeWarningLimit: 3000,
      rollupOptions: standalone
        ? undefined
        : {
            input: {
              main: path.resolve(import.meta.dirname, 'index.html'),
              en: path.resolve(import.meta.dirname, 'en/index.html'),
              team: path.resolve(import.meta.dirname, 'team/index.html'),
              enTeam: path.resolve(import.meta.dirname, 'en/team/index.html'),
            },
          },
    },
  }
})
